<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="no-referrer"><title>Vendor Invitation Link</title><style>body{font:16px system-ui;background:#f5f7fa;color:#10212f;padding:32px}.card{max-width:760px;margin:40px auto;background:white;padding:32px;border-radius:12px;box-shadow:0 2px 12px #0001}input{width:100%;box-sizing:border-box;padding:14px;font-size:15px}button{background:#10212f;color:white;border:0;border-radius:6px;padding:12px 18px;cursor:pointer}</style></head><body><main class="card"><h1>Vendor invitation link</h1><p>This link is shown only once. Copy it now and share it privately with the assigned vendor.</p><input id="link" readonly value="{{ $url }}" aria-label="Vendor link"><p><button type="button" onclick="navigator.clipboard.writeText(document.getElementById('link').value).then(()=>alert('Link copied')).catch(()=>{document.getElementById('link').select();document.execCommand('copy');})">Copy link</button></p><p>Expires: {{ $expiresAt }}</p><p><strong>Security:</strong> Issuing another link invalidates this one. Do not post it publicly.</p><a href="{{ route('rfqs.index') }}">Back to RFQ Register</a></main></body></html>
